@Test
public void readVariables() throws Exception {
    PlcConnection opcuaConnection = new DefaultPlcDriverManager().getConnection(tcpConnectionAddress);
    Condition<PlcConnection> is_connected = new Condition<>(PlcConnection::isConnected, "is connected");
    assertThat(opcuaConnection).is(is_connected);
    PlcReadRequest.Builder builder = opcuaConnection.readRequestBuilder().addTagAddress("Bool", BOOL_IDENTIFIER_READ_WRITE).addTagAddress("Byte", BYTE_IDENTIFIER_READ_WRITE).addTagAddress("Double", DOUBLE_IDENTIFIER_READ_WRITE).addTagAddress("Float", FLOAT_IDENTIFIER_READ_WRITE).addTagAddress("Int16", INT16_IDENTIFIER_READ_WRITE).addTagAddress("Int32", INT32_IDENTIFIER_READ_WRITE).addTagAddress("Int64", INT64_IDENTIFIER_READ_WRITE).addTagAddress("Integer", INTEGER_IDENTIFIER_READ_WRITE).addTagAddress("SByte", SBYTE_IDENTIFIER_READ_WRITE).addTagAddress("String", STRING_IDENTIFIER_READ_WRITE).addTagAddress("UInt16", UINT16_IDENTIFIER_READ_WRITE).addTagAddress("UInt32", UINT32_IDENTIFIER_READ_WRITE).addTagAddress("UInt64", UINT64_IDENTIFIER_READ_WRITE).addTagAddress("UInteger", UINTEGER_IDENTIFIER_READ_WRITE).addTagAddress("BoolArray", BOOL_ARRAY_IDENTIFIER).//.addTagAddress("ByteStringArray", BYTE_STRING_ARRAY_IDENTIFIER);
    addTagAddress("ByteArray", BYTE_ARRAY_IDENTIFIER).addTagAddress("DoubleArray", DOUBLE_ARRAY_IDENTIFIER).addTagAddress("FloatArray", FLOAT_ARRAY_IDENTIFIER).addTagAddress("Int16Array", INT16_ARRAY_IDENTIFIER).addTagAddress("Int32Array", INT32_ARRAY_IDENTIFIER).addTagAddress("Int64Array", INT64_ARRAY_IDENTIFIER).addTagAddress("SByteArray", SBYTE_ARRAY_IDENTIFIER).addTagAddress("StringArray", STRING_ARRAY_IDENTIFIER).addTagAddress("UInt16Array", UINT16_ARRAY_IDENTIFIER).addTagAddress("UInt32Array", UINT32_ARRAY_IDENTIFIER).addTagAddress("UInt64Array", UINT64_ARRAY_IDENTIFIER).addTagAddress("DoesNotExists", DOES_NOT_EXIST_IDENTIFIER_READ_WRITE);
    PlcReadRequest request = builder.build();
    PlcReadResponse response = request.execute().get();
    List.of("Bool", "Byte", "Double", "Float", "Int16", "Int32", "Int64", "Integer", "SByte", "String", "UInt16", "UInt32", "UInt64", "UInteger", "BoolArray", "ByteArray", "DoubleArray", "FloatArray", "Int16Array", "Int32Array", "Int64Array", "SByteArray", "StringArray", "UInt16Array", "UInt32Array", "UInt64Array").forEach(tag -> assertThat(response.getResponseCode(tag)).isEqualTo(PlcResponseCode.OK));
    assertThat(response.getResponseCode("DoesNotExists")).isEqualTo(PlcResponseCode.NOT_FOUND);
    opcuaConnection.close();
    assertThat(opcuaConnection.isConnected()).isFalse();
}

