@Test
public void calculateChecksumTest() {
    DceRpc_Packet packet = new DceRpc_Packet(DceRpc_PacketType.REQUEST, true, false, false, IntegerEncoding.BIG_ENDIAN, CharacterEncoding.ASCII, FloatingPointEncoding.IEEE, new DceRpc_ObjectUuid((byte) 0x00, (short) 0x0001, 0x0002, 0x0493), new DceRpc_InterfaceUuid_DeviceInterface(), new DceRpc_ActivityUuid(0x0aa499a5L, 0x1df0, 0x11b2, new byte[] { (byte) 0x80, (byte) 0x00, (byte) 0xa9, (byte) 0xa2, (byte) 0x59, (byte) 0x4b, (byte) 0x74, (byte) 0x00 }), 0, 0, DceRpc_Operation.CONNECT, (short) 0, new PnIoCm_Packet_Req(16696, 16696, 0, new ArrayList<>()));
    try {
        assertEquals((short) 0x4411, StaticHelper.calculateUdpChecksum(new IpAddress(Hex.decodeHex("c0a85a01")), new IpAddress(Hex.decodeHex("c0a85a80")), 50000, 34964, packet.getLengthInBytes() + 8, packet));
    } catch (DecoderException e) {
        throw new RuntimeException(e);
    }
}

