@Test
public void startTasks() throws Exception {
    log.info("-----------------SinkTaskTest.Put----------------");
    log.info(sinkConnector.toString());
    List<Map<String, String>> config = sinkConnector.taskConfigs(2);
    List<Plc4xSinkTask> sinkList = new ArrayList<>(config.size());
    for (Map<String, String> taskConfig : config) {
        log.info("Starting Sink Task");
        Plc4xSinkTask sinkTask = new Plc4xSinkTask();
        List<SinkRecord> records = new ArrayList<>(1);
        // Build the Schema for the result struct.
        Schema tagSchema = SchemaBuilder.struct().name("org.apache.plc4x.kafka.schema.Field").field("running", Schema.BOOLEAN_SCHEMA).field("numLargeBoxes", Schema.INT32_SCHEMA).build();
        Schema schema = SchemaBuilder.struct().name("org.apache.plc4x.kafka.schema.JobResult").field(Constants.TAGS_CONFIG, tagSchema).field(Constants.TIMESTAMP_CONFIG, Schema.INT64_SCHEMA).field("expires", Schema.OPTIONAL_INT64_SCHEMA).build();
        Struct tagsStruct = new Struct(tagSchema).put("running", false).put("numLargeBoxes", 765);
        Struct struct = new Struct(schema).put("tags", tagsStruct).put(Constants.TIMESTAMP_CONFIG, System.currentTimeMillis()).put("expires", 0L);
        records.add(new SinkRecord("machineSinkA", 1, schema, struct, schema, struct, 1, 0L, TimestampType.CREATE_TIME));
        log.info("Sending Records to Sink task");
        sinkTask.start(taskConfig);
        sinkTask.put(records);
    }
}

